// DecodeMeRequest returns a decoder for requests sent to the identity me
// endpoint.
func DecodeMeRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (*identity.MePayload, error) {
	return func(r *http.Request) (*identity.MePayload, error) {
		var payload *identity.MePayload
		var (
			cookie string
			err    error
		)
		cookie = r.Header.Get("Cookie")
		if cookie == "" {
			err = goa.MergeErrors(err, goa.MissingFieldError("cookie", "header"))
		}
		if err != nil {
			return payload, err
		}
		payload = NewMePayload(cookie)
		if index := strings.IndexByte(string(payload.Cookie), ' '); index >= 0 {
			// Remove authorization scheme prefix (e.g. "Bearer")
			payload.Cookie = payload.Cookie[index+1:]
		}

		return payload, nil
	}
}

